# =====================================================
# HELPERS
# =====================================================
def rate_color(r):
    if r >= 90: return "green"
    if r >= 80: return "orange"
    return "red"

def rate_band(r):
    if r >= 90: return "band-green"
    if r >= 80: return "band-orange"
    return "band-red"

def normaliser_service(f , ville=None):
    if pd.isna(f):
        return "AUTRE"
    f = str(f).upper().strip()
    ville = str(ville).lower().strip() if ville else ""

    if "DECHETS VERTS" in f: return "DECHETS VERTS"
    if f.startswith("COLLECTE"):  return "COLLECTE"
    if "MANUEL"     in f: return "BALAYAGE MANUEL"
    if "ELECTRIQUE" in f: return "BALAYAGE MECANIQUE"
    if "MECANIQUE"  in f: return "BALAYAGE MECANIQUE"
    if "LAVEUSE"    in f: return "LAVAGE MECANIQUE"
    if "LAVAGE"    in f and ville == "tanger":
        return "COLLECTE"
    return "AUTRE"

# =====================================================
# API FUNCTIONS
# =====================================================
def fetch_one_day(session, config_ville, day_str):
    api_url = f"{config_ville['base_url']}/web/dataset/call_kw/fleet.vehicle/get_performance_data"
    payload = {
        "jsonrpc": "2.0", "method": "call",
        "id": int(time.time() * 1000),
        "params": {
            "model": "fleet.vehicle",
            "method": "get_performance_data",
            "args": [],
            "kwargs": {
                "prestation": False, "prefecture": False,
                "arrondissement": False,
                "date_debut": day_str, "date_fin": day_str,
                "kpi_only": False
            }
        }
    }
    r = session.post(api_url, json=payload)
    rows = []
    if r.status_code == 200:
        circuits = r.json().get("result", {}).get("circuits", [])
        for c in circuits:
            row = {
                "cir": c["circuit_name"],
                "fre": c["frequence"],
                "Total constats": c["total_constats_acp"],
                "Total constats prestation": c["total_constats_prestation"],
                "Total pénalité": c["total_penalite"],
                "fonction": c["fonction_name"],
                "ville": config_ville["prefecture"],
                "jour_api": day_str
            }
            for d, v in c["taux_journaliers"].items():
                row[str(d)] = v["taux"]
            rows.append(row)
    return rows

@st.cache_data(ttl=3600)
def load_data_from_api(date_debut, date_fin, config_ville):
    session = requests.Session()
    login_url = f"{config_ville['base_url']}/web/session/authenticate"
    r = session.post(login_url, json={
        "jsonrpc": "2.0",
        "params": {"db": config_ville["db"], "login": LOGIN, "password": PASSWORD}
    })
    if r.status_code != 200 or not r.json().get("result"):
        return pd.DataFrame()

    start = datetime.strptime(date_debut, "%Y-%m-%d")
    end   = datetime.strptime(date_fin,   "%Y-%m-%d")
    days, current = [], start
    while current <= end:
        days.append(current.strftime("%Y-%m-%d"))
        current += timedelta(days=1)

    all_rows = []
    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = [executor.submit(fetch_one_day, session, config_ville, day) for day in days]
        for future in as_completed(futures):
            result = future.result()
            if result:
                all_rows.extend(result)

    return pd.DataFrame(all_rows) if all_rows else pd.DataFrame()

@st.cache_data(ttl=3600)
def load_data_all_villes(date_debut, date_fin):
    dfs = []
    for config in VILLES_CONFIG.values():
        df_v = load_data_from_api(date_debut, date_fin, config)
        if not df_v.empty:
            dfs.append(df_v)
    return pd.concat(dfs, ignore_index=True) if dfs else pd.DataFrame()

# =====================================================
# TRAITEMENT DATAFRAME → df_synthese_jour
# =====================================================
def build_synthese(df_raw):
    df_raw.columns = df_raw.columns.astype(str).str.strip()

    day_cols = [c for c in df_raw.columns if c not in [
        "cir","fre","Total constats","Total constats prestation",
        "Total pénalité","fonction","ville","jour_api"
    ]]

    df_raw["jour_api"] = pd.to_datetime(df_raw["jour_api"], errors="coerce").dt.strftime("%d-%m-%Y")
    # df_raw["service"]  = df_raw["fonction"].apply(normaliser_service)

    df_raw["service"] = df_raw.apply(
        lambda x: normaliser_service(x["fonction"], x["ville"]),
        axis=1
    )

    df_long = df_raw.melt(
        id_vars=["ville","service","fonction","cir","jour_api"],
        value_vars=day_cols,
        var_name="jour", value_name="score"
    )
    df_long["score"] = pd.to_numeric(df_long["score"], errors="coerce")
    df_long = df_long.dropna(subset=["score"])

    df_long = df_long[~df_long["service"].isin(["AUTRE", "DECHETS VERTS"])]
    df_raw  = df_raw[~df_raw["service"].isin(["AUTRE", "DECHETS VERTS"])]

    df_circuit_jour = (
        df_long
        .groupby(["jour_api","ville","service","cir"], as_index=False)
        .agg(Taux_jour_circuit=("score","mean"))
    )

    df_circuit_jour = df_circuit_jour.merge(
        df_raw[["jour_api","ville","service","fonction","cir",
                "Total constats","Total constats prestation","Total pénalité"]],
        on=["jour_api","ville","service","cir"],
        how="left"
    )

    df_synthese = (
        df_circuit_jour
        .groupby(["jour_api","ville","service"], as_index=False)
        .apply(lambda x: pd.Series({
            "Moyenne_taux": (
                (x["Taux_jour_circuit"] * x["Total constats"]).sum()
                / x["Total constats"].sum()
                if x["Total constats"].sum() > 0 else 0
            ),
            "Total_constats": x["Total constats"].sum(),
            "Total_constats_prestation": x["Total constats prestation"].sum(),
            "Total_penalite": x["Total pénalité"].sum()
        }))
    )

    df_synthese["Moyenne_taux"] = df_synthese["Moyenne_taux"].round(4)
    return df_synthese.sort_values(["jour_api","ville","service"])

def build_circuits_classes(df_raw):
    df = df_raw.copy()

    # df["service"] = df["fonction"].apply(normaliser_service)
    df["service"] = df.apply(
        lambda x: normaliser_service(x["fonction"], x["ville"]),
        axis=1
    )

    df = df[~df["service"].isin(["AUTRE", "DECHETS VERTS"])]

    # Colonnes jours
    day_cols = [c for c in df.columns if c not in [
        "cir","fre","Total constats","Total constats prestation",
        "Total pénalité","fonction","ville","jour_api","service"
    ]]

    df_long = df.melt(
        id_vars=["ville","service","cir","jour_api"],
        value_vars=day_cols,
        var_name="jour",
        value_name="score"
    )

    df_long["score"] = pd.to_numeric(df_long["score"], errors="coerce")
    df_long = df_long.dropna(subset=["score"])

    # Moyenne par circuit / jour
    df_circuit = (
        df_long.groupby(["jour_api","ville","service","cir"], as_index=False)
        .agg(taux=("score","mean"))
    )

    # Classification
    def classe(x):
        if x == 0:
            return "Non exécuté"
        elif x < 70:
            return "<70%"
        elif x < 80:
            return "70% - 80%"
        elif x < 90:
            return "80% - 90%"
        elif x < 95:
            return "90% - 95%"
        else:
            return "95% - 100%"

    df_circuit["classe"] = df_circuit["taux"].apply(classe)

    return df_circuit
