with col_contra:
    SEUIL = 90
    COLOR_MAP_CP = {"green": "#1a9e3f", "orange": "#e87c1e", "red": "#d32f2f"}

    def svc_taux(x):
        tc = x["Total_constats"].sum()
        return (x["Moyenne_taux"] * x["Total_constats"]).sum() / tc if tc > 0 else 0

    df_svc_cp = (
        df_day.groupby(["ville", "service"], as_index=False)
        .apply(lambda x: pd.Series({"Taux_service": svc_taux(x)}))
    )

    df_taux_ville_cp = (
        df_svc_cp.groupby("ville", as_index=False)
        .agg(Taux_global_ville=("Taux_service", "mean"))
    )

    df_contre = df_taux_ville_cp[df_taux_ville_cp["Taux_global_ville"] < SEUIL].sort_values("Taux_global_ville")

    cp_title = "⚠️ Site(s) en contre-performance opérationnelle" if not is_toute_periode \
               else "⚠️ Site(s) en contre-performance (moyenne période)"
    st.markdown(f'<div class="contre-perf-title">{cp_title}</div>', unsafe_allow_html=True)

    if df_contre.empty:
        st.markdown("""
        <div class="contre-perf-body">
          <p style="color:#1a9e3f;font-weight:600;margin:0;">
            ✅ Aucun site en contre-performance pour cette période.
          </p>
        </div>""", unsafe_allow_html=True)
    else:
        items_html = ""
        for _, row in df_contre.iterrows():
            ville_name = row["ville"].capitalize()
            taux_v     = row["Taux_global_ville"]
            col_v      = rate_color(taux_v)
            col_v_hex  = COLOR_MAP_CP[col_v]

            svcs = df_svc_cp[df_svc_cp["ville"] == row["ville"]].sort_values("Taux_service")
            details_parts = []
            for _, sr in svcs.iterrows():
                ts  = sr["Taux_service"]
                thx = COLOR_MAP_CP[rate_color(ts)]
                details_parts.append(
                    "<span style='color:" + thx + ";font-weight:700'>" +
                    sr["service"].title() + " : " + f"{ts:.1f}%" + "</span>"
                )
            details_str = " | ".join(details_parts)

            items_html += (
                '<div class="contre-perf-item"><span>📍</span><span>' +
                f"<b>{ville_name}</b> : " +
                f"<span style='color:{col_v_hex};font-weight:700'>{taux_v:.1f} %</span>" +
                (f" — {details_str}" if details_str else "") +
                "</span></div>"
            )

        st.markdown(f'<div class="contre-perf-body">{items_html}</div>', unsafe_allow_html=True)



    # =====================================================
    # TABLEAU : CIRCUITS PENALISES PAR SERVICE
    # =====================================================

    df_raw = st.session_state.get("df_raw")

    if df_raw is not None and not df_raw.empty:

        df_circuit_all = build_circuits_classes(df_raw)

        # Appliquer filtres dashboard
        if not is_toute_periode:
            df_circuit_all = df_circuit_all[df_circuit_all["jour_api"] == date_sel]

        if ville_sel != "Toutes les villes":
            df_circuit_all = df_circuit_all[df_circuit_all["ville"] == ville_sel]

        ordre_colonnes = [
            "Non exécuté", "<70%", "70% - 80%",
            "80% - 90%", "90% - 95%", "95% - 100%"
        ]

        df_table = (
            df_circuit_all
            .groupby(["service","classe"])
            .size()
            .unstack(fill_value=0)
        )

        # Garantir colonnes
        for col in ordre_colonnes:
            if col not in df_table.columns:
                df_table[col] = 0

        df_table = df_table[ordre_colonnes]

        # Total
        df_table["Total"] = df_table.sum(axis=1)

        df_table = df_table.reset_index()

        # ── UI ─────────────────────────────────────────────
        st.markdown("<br>", unsafe_allow_html=True)

        st.markdown("""
        <div style="background:#0d2757;color:white;
        padding:10px 20px;border-radius:10px 10px 0 0;
        font-family:Montserrat;font-weight:700;">
        📊 Nombre de circuits pénalisés par service
        </div>
        """, unsafe_allow_html=True)

        st.dataframe(df_table, use_container_width=True)


